// BestTV — FB/IG webhook-оос мессеж/postback задлах.
// FB:  body.object === 'page',       entry[].messaging[]
// IG:  body.object === 'instagram',  entry[].messaging[]
const body = $input.first().json.body;

// ⚠️ DEDUP — FB нэг мессежийг 2 удаа (retry) илгээдэг. mid-ийг санана.
var _sd = $getWorkflowStaticData('global');
_sd.seenMids = _sd.seenMids || [];
function _dup(mid){ if(!mid)return false; if(_sd.seenMids.indexOf(mid)!==-1)return true; _sd.seenMids.push(mid); if(_sd.seenMids.length>200)_sd.seenMids=_sd.seenMids.slice(-200); return false; }

// ⚠️ Comment event (changes) Messenger salaa руу ОРОХГҮЙ
{ const e0=(body&&body.entry&&body.entry[0])||{}; if(e0.changes && !e0.messaging) return []; }
if (!body) return [];

let platform = '';
if (body.object === 'page') platform = 'facebook';
else if (body.object === 'instagram') platform = 'instagram';
else return [];

// Get Started / Ice Breaker payload → текст асуулт
const PAYLOAD_TO_TEXT = {
  GET_STARTED: '__GET_STARTED__',
  IB_MOVIES: 'шинэ кино',
  IB_SERIES: 'цуврал',
  IB_PRICING: 'багцын үнэ',
  IB_HOWTO: 'яаж үзэх вэ',
};

const out = [];
for (const entry of (body.entry || [])) {
  for (const msg of (entry.messaging || [])) {
    const psid = String(msg.sender && msg.sender.id || '');
    if (!psid) continue;
    // Өөрийн Page/IG-ээс ирсэн бол алгасна (давталтаас сэргийлнэ)
    if (psid === '108103720808038' || psid === '17841442595556819') continue;

    if (msg.postback && msg.postback.payload) {
      const mapped = PAYLOAD_TO_TEXT[msg.postback.payload];
      const text = mapped || String(msg.postback.title || msg.postback.payload).trim();
      out.push({ json: { psid, text, isPostback: true, platform } });
      continue;
    }
    if (msg.message && msg.message.mid && _dup(msg.message.mid)) continue;
    if (msg.message && !msg.message.is_echo && msg.message.text) {
      out.push({ json: { psid, text: String(msg.message.text).trim(), isPostback: false, platform } });
      continue;
    }

    /**
     * ⚠️⚠️ ЗУРАГ / ФАЙЛ / СТИКЕР — өмнө нь БҮРЭН ЧИМЭЭГҮЙ алгасагддаг байв.
     *
     * BestTV-д дансаар шилжүүлсэн БАРИМТЫН ЗУРАГ илгээх нь бодит
     * хэрэглээ. Хариу огт өгөхгүй бол хэрэглэгч «бот үхсэн» гэж
     * бодож орхино — мөнгө төлсөн хүн хариу хүлээхгүй байх нь ноцтой.
     *
     * ⚠️ Стикер/лайкийг ялгана — тэдэнд «баримт хүлээж авлаа» гэвэл
     * утгагүй. Стикерт огт хариу өгөхгүй (спам болно).
     */
    if (msg.message && !msg.message.is_echo && !msg.message.text) {
      var atts = msg.message.attachments || [];
      var isSticker = false;
      var kind = '';
      for (var ai = 0; ai < atts.length; ai++) {
        var ty = atts[ai].type || '';
        if (ty === 'image' && atts[ai].payload && atts[ai].payload.sticker_id) isSticker = true;
        if (!kind && (ty === 'image' || ty === 'file' || ty === 'video')) kind = ty;
      }
      if (isSticker || !kind) continue;
      /* ⚠️ URL-ыг ДАМЖУУЛНА — backend R2 руу хуулж мөнхжүүлнэ.
         Meta-гийн CDN линк хэдэн цагийн дараа 403 болно. */
      var attUrl = '';
      for (var au = 0; au < atts.length; au++) {
        if (atts[au].payload && atts[au].payload.url) { attUrl = atts[au].payload.url; break; }
      }
      out.push({ json: { psid, text: '__ATTACHMENT__', attKind: kind, attUrl: attUrl, isPostback: false, platform } });
    }
  }
}
return out;

// BestTV — AI Agent-аас ӨМНӨ. psid/userText/firstName бэлдэнэ.
const NL = String.fromCharCode(10);
const psid = $('Parse').first().json.psid;
const userText = $('Parse').first().json.text;
const platform = $('Parse').first().json.platform || 'facebook';
const _conv = $('Get User Profile').first().json || {};
var _name = String(_conv.name || _conv.first_name || _conv.username || '').trim();
var _pic = String(_conv.profile_pic || '').trim();
const firstName = _name;
const profilePic = _pic;
const isGetStarted = (userText === '__GET_STARTED__');
const nameLine = firstName ? ('Хэрэглэгчийн нэр: ' + firstName) : '';

// ⚠️ ЗУРАГ/ФАЙЛ — AI руу явуулахгүй (зураг харж чадахгүй, утгагүй
// хариу зохионо). Оронд нь тодорхой заавар өгнө. Build Messages нь
// энэ directReply-г AI-аас ДЭЭГҮҮР ашиглана.
const attKind = $('Parse').first().json.attKind || '';
const attUrl = $('Parse').first().json.attUrl || '';
if (userText === '__ATTACHMENT__') {
  const what = attKind === 'video' ? 'Бичлэг' : (attKind === 'file' ? 'Файл' : 'Зураг');
  return [{ json: { psid, userText: '(' + what.toLowerCase() + ' илгээв)', firstName, profilePic,
    platform, isGetStarted: false, attKind, attUrl,
    directReply: what + ' хүлээж авлаа 📩' + NL + NL +
      'Хэрэв дансаар шилжүүлсэн баримт бол манай ажилтан ажлын өдрийн ' +
      '10:00–18:00 цагт шалгаж баталгаажуулна.' + NL + NL +
      'Асуух зүйл байвал бичээрэй 😊',
    agentInput: '(хэрэглэгч ' + what.toLowerCase() + ' илгээв)' } }];
}

// ⚠️ Холбоо барих/багцын асуултад AI зохиодог тул deterministic хариу
// бэлдэнэ (Build Messages түүнийг AI-аас ДЭЭГҮҮР ашиглана).
const _rawLower = (userText || '').toLowerCase();

/**
 * ⚠️⚠️ ГАЛИГ (Латинаар бичсэн монгол) → Кирилл ойролцоо хөрвүүлэлт.
 *
 * ЯАГААД ЗААВАЛ: хэрэглэгчид утсаараа «yaj bvrtgvvlehiin», «tulbur»,
 * «bagts» гэж ЛАТИНААР бичдэг. Бүх trigger жагсаалт КИРИЛЛ тул огт
 * таарахгүй → асуулт «кино хайлт» болж «олдсонгүй 🙁» гэсэн утгагүй
 * хариу очиж байсан (бодит гомдол, 2026-08-24).
 *
 * ⚠️ Энэ нь ЗӨВХӨН intent таних зорилготой ойролцоо хувиргалт —
 * үсэг тус бүрийг төгс сэргээх шаардлагагүй, түлхүүр үг таарвал хангалттай.
 * ⚠️ v/w = ү/ө (bvrtgvvleh = бүртгүүлэх) — энгийн галигийн заншил.
 *    backend-ийн latinToCyrVariants үүнийг хамардаггүй тул энд тусад нь.
 */
/**
 * ⚠️ ЯГ ТААРУУЛАХ БИШ — «АРАН ЯС» (skeleton) харьцуулна.
 *
 * Галигийн бичлэг нэг мөр биш: «tulbur/tulbor/tolbor», «burtguuleh/
 * bvrtgvvleh» бүгд «төлбөр/бүртгүүлэх». Эгшгийн урт, ө/ү/у/о ялгааг
 * ТААМАГЛАХ гэж оролдвол заавал алдана. Тиймээс хоёр талын үгийг
 * ижил аргаар ГУЙВУУЛЖ (эгшгийг хаяж, давхар гийгүүлэгчийг нэгтгэж)
 * харьцуулна — «tlbr» = «тлбр» → таарна.
 */
function _skel(s) {
  if (!s) return '';
  var lat = s.toLowerCase();
  /* Кирилл → латин суурь (эгшгийг дараа нь хаяна тул ө/ү/у ялгаа хамаагүй) */
  var cyr = [
    ['ш','sh'],['щ','sh'],['ч','ch'],['ц','ts'],['я','ya'],['ё','yo'],['ю','yu'],
    ['ж','j'],['х','h'],['ъ',''],['ь',''],['ы','i'],['э','e'],['ө','o'],['ү','u'],
    ['а','a'],['б','b'],['в','v'],['г','g'],['д','d'],['е','e'],['з','z'],['и','i'],
    ['й','i'],['к','k'],['л','l'],['м','m'],['н','n'],['о','o'],['п','p'],['р','r'],
    ['с','s'],['т','t'],['у','u'],['ф','f'],
  ];
  for (var i = 0; i < cyr.length; i++) lat = lat.split(cyr[i][0]).join(cyr[i][1]);
  /* Галигийн ижил утгатай бичлэгүүдийг нэг болгоно */
  lat = lat.split('kh').join('h').split('ts').join('c').split('ch').join('c')
           .split('sh').join('s').split('w').join('u').split('v').join('u')
           .split('y').join('i').split('q').join('k').split('x').join('h');
  /* ⚠️ ЭГШГИЙГ БҮРЭН ХАЯНА — «tulbur/tolbor/төлбөр» бүгд «tlbr» болно */
  lat = lat.replace(/[aeiou]/g, '');
  /* Давхар гийгүүлэгч → ганц (bvrtgvvleh → brtglh) */
  lat = lat.replace(/([a-z])\1+/g, '$1');
  return lat;
}
/**
 * Түлхүүр үгийн аль нэг нь бичвэрт (аран ясаар) байгаа эсэх.
 * ⚠️ Эхлээд ЭНГИЙН substring (кирилл/англиар зөв бичсэн тохиолдол,
 *    хамгийн найдвартай), дараа нь аран ясаар (галиг).
 */
function _hits(text, list) {
  var raw = (text || '').toLowerCase();
  for (var i = 0; i < list.length; i++) {
    if (raw.indexOf(list[i]) !== -1) return true;
  }
  var sk = _skel(raw);
  /* ⚠️ Богино аран яс (<3) санамсаргүй таарна — алгасна */
  for (var j = 0; j < list.length; j++) {
    var ks = _skel(list[j]);
    if (ks.length >= 3 && sk.indexOf(ks) !== -1) return true;
  }
  return false;
}
const lower = _rawLower;
const contactTriggers = ['утас','дугаар','хаяг','холбоо','холбогд','имэйл','мэйл',
  'байршил','ажлын цаг','социал','фэйсбүүк','facebook','instagram','инстаграм',
  'бидний тухай','танай тухай','хэн бэ','хаягтай','утастай','phone','contact'];
const _hasEmailAddr = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(userText || '');
const needsContact = !_hasEmailAddr && _hits(lower, contactTriggers);

let directReply = '';
if (needsContact) {
  try {
    const s = await this.helpers.httpRequest({
      method: 'GET', url: 'http://besttv-backend:4100/api/settings/socials', json: true, timeout: 4000,
      /* ⚠️ throttle-ыг тойрно — 30 хүсэлтээс 10 нь 429 болдог байв,
         тэгэхэд directReply хоосон үлдэж AI холбоо барихыг ЗОХИОНО */
      headers: { 'x-bot-secret': '__BOT_SECRET__' },
    });
    const parts = ['📺 BestTV — Монголын кино, цувралын онлайн сан', ''];
    if (s && s.phone) parts.push('📞 Утас: ' + s.phone);
    /**
     * ⚠️⚠️ ИМЭЙЛ ЗААВАЛ ГАРНА — админ socials-д тохируулаагүй ч.
     *
     * БОДИТ АЛДАА: Settings.socials бүх талбар ХООСОН байсан тул
     * «холбоо барих» асуултад чатбот зөвхөн вэб хаяг өгч, хэрэглэгч
     * хаана хандахаа мэдэхгүй үлддэг байв. Тохиргоо хоосон байх нь
     * хэрэглэгчид хариу өгөхгүй байх ШАЛТГААН БИШ.
     */
    parts.push('✉️ Имэйл: ' + ((s && s.email) || 'support@besttv.us'));
    if (s && s.facebook) parts.push('💬 Facebook: ' + s.facebook);
    if (s && s.instagram) parts.push('📷 Instagram: ' + s.instagram);
    parts.push('', '🌐 Вэб: https://besttv.us');
    parts.push('', 'Эсвэл энд шууд бичээрэй — админ хариулна 😊');
    directReply = parts.join(NL);
  } catch (e) {
    /* ⚠️ API унасан ч ХООСОН БУЦААХГҮЙ — өмнө нь directReply=''
       болоод AI холбоо барих мэдээллийг ЗОХИОДОГ байв (худал утас/
       имэйл өгөх эрсдэл). Хамгийн багадаа имэйл + вэб хаягийг өгнө. */
    directReply = ['📺 BestTV — Монголын кино, цувралын онлайн сан', '',
      '✉️ Имэйл: support@besttv.us', '', '🌐 Вэб: https://besttv.us', '',
      'Эсвэл энд шууд бичээрэй — админ хариулна 😊'].join(NL);
  }
}

// ⚠️ БАГЦЫН ҮНЭ — AI үнэ зохиовол хэрэглэгч төөрөлдөнө. Бодит үнийг татна.
const priceTriggers = ['багц','үнэ','төлбөр','хэд вэ','ханш','тариф','захиалга','subscribe','price'];
const needsPricing = _hits(lower, priceTriggers);
let plansText = '';
if (needsPricing) {
  try {
    const plans = await this.helpers.httpRequest({
      method: 'GET', url: 'http://besttv-backend:4100/api/plans', json: true, timeout: 4000,
      /* ⚠️ throttle → 429 → AI ҮНЭ ЗОХИОНО. Яг сэргийлэх гэсэн зүйл. */
      headers: { 'x-bot-secret': '__BOT_SECRET__' },
    });
    if (Array.isArray(plans) && plans.length) {
      const fmt = function(n){ var s=String(Math.round(Number(n)||0)),o='',c=0;
        for(var i=s.length-1;i>=0;i--){o=s[i]+o;c++;if(c%3===0&&i>0)o=','+o;} return o+'₮'; };
      const lines = ['📦 BestTV-ийн багцууд:', ''];
      plans.forEach(function(p){
        lines.push('• ' + p.name + ' — ' + fmt(p.price) + ' / ' + p.durationDays + ' хоног');
        if (p.description) lines.push('  ' + p.description);
      });
      lines.push('', '👉 Багц авах: https://besttv.us/pricing');
      plansText = lines.join(NL);
    }
  } catch (e) { plansText = ''; }
}
if (plansText) directReply = plansText;

/**
 * ⚠️⚠️ ДАНСНЫ МЭДЭЭЛЭЛ — AI-д ХЭЗЭЭ Ч ЗОХИОЛГОХГҮЙ.
 *
 * Буруу дансны дугаар өгвөл хэрэглэгчийн МӨНГӨ ӨӨР ХҮН РҮҮ очно —
 * буцаах боломжгүй, платформын нэр хүнд унана. Тиймээс бодит дансыг
 * DB-ээс татаж deterministic хариу бэлдэнэ.
 *
 * ⚠️ ГҮЙЛГЭЭНИЙ УТГА нь хэрэглэгч/захиалга бүрт ӨӨР (жишээ BTV-XXXX)
 *    тул ЭНД бичихгүй — сайтаас авахыг зааварчилна.
 */
const bankTriggers = ['данс','дансаар','шилжүүл','хаан банк','хаанбанк','голомт',
  'хас банк','төрийн банк','account','гүйлгээ','дансны дугаар'];
const needsBank = _hits(lower, bankTriggers);
if (needsBank) {
  try {
    /* ⚠️ Зам нь /bank/accounts — /settings/bank БАЙХГҮЙ (404).
       Олон данс байж болно тул идэвхтэйг нь бүгдийг харуулна. */
    const b = await this.helpers.httpRequest({
      method: 'GET', url: 'http://besttv-backend:4100/api/bank/accounts', json: true, timeout: 4000,
      headers: { 'x-bot-secret': '__BOT_SECRET__' },
    });
    const accs = (b && Array.isArray(b.accounts))
      ? b.accounts.filter(function (a) { return a && a.isActive && a.accountNumber; })
      : [];
    if (b && b.enabled && accs.length) {
      const bl = ['🏦 Дансаар шилжүүлэх:', ''];
      accs.forEach(function (a) {
        bl.push((a.bankName ? a.bankName + ': ' : '') + a.accountNumber
          + (a.accountName ? '  (' + a.accountName + ')' : ''));
      });
      bl.push('', '⚠️ ГҮЙЛГЭЭНИЙ УТГЫГ заавал бичнэ — сайт дээр багцаа',
        'сонгоод «Дансаар шилжүүлэх» гэхэд ТАНД зориулсан утга гарна.',
        '', 'Шилжүүлээд баримтын зургаа энд илгээгээрэй 📷');
      if (b.note) bl.push('', b.note);
      bl.push('', '👉 https://besttv.us/pricing');
      directReply = bl.join(NL);
    }
  } catch (e) {
    /* ⚠️ API унасан ч AI-д данс зохиолгохгүй — заавар руу чиглүүлнэ */
    directReply = ['🏦 Дансаар шилжүүлэх:', '',
      'Сайт дээр багцаа сонгоод «Дансаар шилжүүлэх» гэхэд дансны',
      'дугаар болон ТАНД зориулсан гүйлгээний утга гарч ирнэ.',
      '', 'Шилжүүлээд баримтын зургаа энд илгээгээрэй 📷',
      '', '👉 https://besttv.us/pricing'].join(NL);
  }
}

/**
 * ⚠️⚠️ ЗААВАР (бүртгүүлэх / нэвтрэх / яаж төлөх / яаж үзэх).
 *
 * ЯАГААД ЗААВАЛ DETERMINISTIC: «yaj bvrtgvvlehiin» гэсэн асуултад бот
 * «кино олдсонгүй 🙁» гэж хариулж байсан (бодит гомдол) — учир нь
 * заавар гэсэн ойлголт ОГТ БАЙГААГҮЙ, бүх зүйл кино хайлт руу унадаг
 * байв. AI-д даалгавал алхмуудыг зохиож, буруу зам заана.
 *
 * ⚠️ Дараалал ЧУХАЛ: энэ шалгалт үнэ/данс/холбоо барихаас ХОЙНО байна —
 * «багц яаж авах» гэвэл үнийн жагсаалт нь илүү хэрэгтэй.
 */
if (!directReply) {
  /* ⚠️ Товчилсон/ярианы хэлбэрийг ч барина («нэвтрэй», «бүртгүүлье») */
  var howtoTriggers = ['бүртгүүлэх','бүртгүүл','бүртгэл','нэвтрэх','нэвтэрч',
    'нэвтрэй','нэвтэр','хаяг нээх','бүртгүүлье','яаж эхлэх','sign up','signup',
    'register','login'];
  var payHowTriggers = ['яаж төлөх','төлбөр төлөх','хэрхэн төлөх','карт','картаар',
    'visa','mastercard','apple pay','google pay','wechat','хэтэвч','цэнэглэх','pay'];
  var watchTriggers = ['яаж үзэх','хэрхэн үзэх','яаж орох','заавар'];
  var isHowto = _hits(lower, howtoTriggers);
  var isPayHow = _hits(lower, payHowTriggers);
  var isWatch = _hits(lower, watchTriggers);

  if (isHowto || isPayHow || isWatch) {
    var g = [];
    if (isHowto) {
      g.push('📝 Бүртгүүлж эхлэх (1 минут):', '',
        '1️⃣ https://besttv.us нээнэ',
        '2️⃣ Баруун дээд булан дахь «Нэвтрэх» дарна',
        '3️⃣ Имэйл хаягаа бичээд нууц үгээ үүсгэнэ',
        '4️⃣ Имэйлд ирсэн кодоор баталгаажуулна',
        '', '✅ Бүртгэл үнэгүй. Бүртгүүлээд багцаа сонгоно.');
    }
    if (isPayHow) {
      if (g.length) g.push('');
